cypress_script:
describe('Mobile viewport product browsing via burger menu', () => {
  it('should open and close the burger menu', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[data-test="react-burger-menu-btn"]').click();
    cy.get('[data-test="inventory-sidebar-link"]').should('be.visible');
    cy.get('[data-test="react-burger-cross-btn"]').click();
    cy.get('[data-test="inventory-sidebar-link"]').should('not.be.visible');
  });

  it('should not navigate when opening the menu', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[data-test="react-burger-menu-btn"]').click();
    cy.url().should('eq', 'https://www.saucedemo.com/inventory.html');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Mobile viewport product browsing via burger menu', () => {
  test('should open and close the burger menu', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await page.click('[data-test="react-burger-menu-btn"]');
    await expect(page.locator('[data-test="inventory-sidebar-link"]')).toBeVisible();
    await page.click('[data-test="react-burger-cross-btn"]');
    await expect(page.locator('[data-test="inventory-sidebar-link"]')).not.toBeVisible();
  });

  test('should not navigate when opening the menu', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await page.click('[data-test="react-burger-menu-btn"]');
    await expect(page.url()).toBe('https://www.saucedemo.com/inventory.html');
  });
});
